DO $$
DECLARE expected_table_count constant integer := 8; actual_tables text[]; columns_hash text; constraints_hash text; indexes_hash text; acl_hash text; trigger_hash text; function_hash text; effective_acl_hash text;
BEGIN
  IF current_setting('ai_mls.r3b1_publication_artifact_sha256', true) <> '613ecc0dfbe1a2ffd2d2edcdbda1d27b55713b8bcd09be6bc6e7bdbb7871d885' THEN RAISE EXCEPTION 'publication migration checksum mismatch'; END IF;
  IF obj_description('app_publication'::regnamespace, 'pg_namespace') <> 'REL002-R3B1-PUBLICATION-V1|schema_version=1|contract_fingerprint=pub-v1-8-tables' THEN RAISE EXCEPTION 'publication schema version or contract fingerprint mismatch'; END IF;
  SELECT array_agg(tablename ORDER BY tablename) INTO actual_tables FROM pg_tables WHERE schemaname = 'app_publication';
  IF cardinality(actual_tables) <> expected_table_count OR actual_tables <> ARRAY['publication_audit','publication_dispatch_events','publication_events','publication_execution_intents','publication_execution_receipts','publication_idempotency','publication_schema','publication_scopes'] THEN RAISE EXCEPTION 'publication unexpected table inventory mismatch'; END IF;
  IF NOT EXISTS (SELECT 1 FROM app_publication.publication_schema WHERE singleton_id=1 AND schema_version=1 AND contract_fingerprint='pub-v1-8-tables') THEN RAISE EXCEPTION 'publication schema_version contract_fingerprint mismatch'; END IF;
  SELECT md5(string_agg(concat_ws('|',table_name,ordinal_position,column_name,data_type,udt_name,is_nullable,coalesce(column_default,'')),E'\n' ORDER BY table_name,ordinal_position)) INTO columns_hash FROM information_schema.columns WHERE table_schema='app_publication';
  SELECT md5(string_agg(concat_ws('|',r.relname,c.conname,c.contype,pg_get_constraintdef(c.oid,true)),E'\n' ORDER BY r.relname,c.conname)) INTO constraints_hash FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='app_publication';
  SELECT md5(string_agg(concat_ws('|',t.relname,i.relname,pg_get_indexdef(x.indexrelid)),E'\n' ORDER BY t.relname,i.relname)) INTO indexes_hash FROM pg_index x JOIN pg_class t ON t.oid=x.indrelid JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='app_publication';
  IF columns_hash<>'7ec75fcc4191f132cac4a5ee7f2607ab' OR constraints_hash<>'6ba8469f5859fb9e951e6f09872823d0' OR indexes_hash<>'d3837969e1fd6b51c2169629198fa10a' THEN RAISE EXCEPTION 'publication columns constraints indexes mismatch'; END IF;
  IF pg_get_userbyid((SELECT nspowner FROM pg_namespace WHERE nspname='app_publication'))<>'ai_mls_production_migration_operator' OR EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='app_publication' AND tableowner<>'ai_mls_production_migration_operator') THEN RAISE EXCEPTION 'publication ownership mismatch'; END IF;
  SELECT md5(string_agg(concat_ws('|',r.relname,t.tgname,t.tgenabled,t.tgtype,pn.nspname,p.proname,pg_get_triggerdef(t.oid,true)),E'\n' ORDER BY r.relname,t.tgname)) INTO trigger_hash FROM pg_trigger t JOIN pg_class r ON r.oid=t.tgrelid JOIN pg_namespace n ON n.oid=r.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE n.nspname='app_publication' AND NOT t.tgisinternal;
  SELECT md5(string_agg(concat_ws('|',p.proname,l.lanname,pg_get_function_result(p.oid),trim(p.prosrc),pg_get_userbyid(p.proowner),p.prosecdef,coalesce(array_to_string(p.proconfig,','),'')),E'\n' ORDER BY p.proname)) INTO function_hash FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='app_publication';
  IF trigger_hash<>'773fbb636bd1120600e6b87020c93af4' OR function_hash<>'c55bb1de5ccba2b1308a21316f1acaa0' THEN RAISE EXCEPTION 'publication exact trigger/function topology mismatch'; END IF;
  IF has_schema_privilege('ai_mls_production_runtime','app_publication','CREATE') OR NOT has_schema_privilege('ai_mls_production_runtime','app_publication','USAGE') THEN RAISE EXCEPTION 'publication runtime schema ACL mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname='app_publication' AND (NOT has_table_privilege('ai_mls_production_runtime',format('%I.%I',schemaname,tablename),'SELECT') OR has_table_privilege('ai_mls_production_runtime',format('%I.%I',schemaname,tablename),'DELETE,TRUNCATE,REFERENCES,TRIGGER'))) THEN RAISE EXCEPTION 'publication runtime table ACL mismatch'; END IF;
  SELECT md5(string_agg(concat_ws('|',table_name,privilege_type,is_grantable),E'\n' ORDER BY table_name,privilege_type)) INTO acl_hash FROM information_schema.role_table_grants WHERE table_schema='app_publication' AND grantee='ai_mls_production_runtime';
  IF acl_hash<>'8f0a2ed43d7dd7ce7ea0e5a2a5803449' THEN RAISE EXCEPTION 'publication exact runtime DML mismatch'; END IF;
  SELECT md5(string_agg(concat_ws('|',t.tablename,has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'SELECT'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'INSERT'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'UPDATE'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'DELETE'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'TRUNCATE'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'REFERENCES'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',t.schemaname,t.tablename),'TRIGGER')),E'\n' ORDER BY t.tablename)) INTO effective_acl_hash FROM pg_tables t WHERE t.schemaname='app_publication';
  IF effective_acl_hash<>'df8a0c41f873818a01aedbf9c1bdd49a' THEN RAISE EXCEPTION 'publication effective runtime ACL mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM pg_class r CROSS JOIN LATERAL aclexplode(coalesce(r.relacl,acldefault('r',r.relowner))) a WHERE r.relnamespace='app_publication'::regnamespace AND r.relkind='r' AND (a.grantee NOT IN (r.relowner,(SELECT oid FROM pg_roles WHERE rolname='ai_mls_production_runtime')) OR (a.grantee=(SELECT oid FROM pg_roles WHERE rolname='ai_mls_production_runtime') AND a.is_grantable))) THEN RAISE EXCEPTION 'publication PUBLIC leakage, unexpected grantee, or grant option'; END IF;
  IF EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='app_publication' AND (a.grantee NOT IN (n.nspowner,(SELECT oid FROM pg_roles WHERE rolname='ai_mls_production_runtime')) OR (a.grantee=(SELECT oid FROM pg_roles WHERE rolname='ai_mls_production_runtime') AND (a.privilege_type<>'USAGE' OR a.is_grantable)))) OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='app_publication' AND a.grantee<>p.proowner) THEN RAISE EXCEPTION 'publication schema/function ACL leakage'; END IF;
  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='app_publication' AND p.proname='reject_append_only_mutation' AND pg_get_userbyid(p.proowner)='ai_mls_production_migration_operator' AND position('append-only' IN p.prosrc)>0)<>1 OR EXISTS(SELECT 1 FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='app_publication' AND r.relkind='S') THEN RAISE EXCEPTION 'publication function/sequence mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM pg_auth_members WHERE member IN (SELECT oid FROM pg_roles WHERE rolname IN ('ai_mls_production_runtime','ai_mls_production_migration_operator'))) OR EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles granted ON granted.oid=m.roleid JOIN pg_roles member_role ON member_role.oid=m.member WHERE granted.rolname IN ('ai_mls_production_runtime','ai_mls_production_migration_operator') AND member_role.rolname<>'postgres') THEN RAISE EXCEPTION 'publication unexpected role membership'; END IF;
END $$;
